platform.charts/receiver/templates/configmap.yaml:
apiVersion: v1
kind: ConfigMap
metadata:
  name: receiver-config
data:
  receiver.yaml: |
    listen: {{ .Values.receiver.listen | default "0.0.0.0:4318" }}
    batch_size: {{ .Values.receiver.batchSize | default 512 }}
    queue_capacity: {{ .Values.receiver.queueCapacity | default 4096 }}

platform.src/toolsets.py:
def validate_toolset(tools):
    """Reject oversized toolsets before registration."""
    if len(tools) > 32:
        raise ValueError("toolset contains more than 32 tools")
    return tools

platform.src/payload.py:
def accept_payload(body):
    """The receiver rejects a payload larger than one mebibyte."""
    if len(body) > 1024 * 1024:
        raise ValueError("payload exceeds receiver byte limit")
    return body

platform.src/retries.py:
def retry_delay(attempt):
    """Receiver retries use exponential backoff capped at thirty seconds."""
    return min(30, 2 ** attempt)

coding-plugin.src/telemetry.py:
def send_agent_spans(tracer, session):
    """The coding-agent plugin sends session, tool-call and completion spans."""
    for name in ("agent.session", "agent.tool_call", "agent.completion"):
        tracer.emit(name, session=session)
